function submitWord(skip){if(!wordTestSession||wordTestSession.answered)return;const v=wordTestSession.queue[wordTestSession.index],mode=wordTestSession.mode;if(!skip&&mode==='missing'&&!missingInputsReady()){$$('.missing-letter-input').find(input=>!String(input.value||'').trim())?.focus();return}const a=skip?'':(mode==='missing'?missingAnswerFromInputs(v):($('#wordTestInput')?.value||'').trim());if(!skip&&!a)return;const target=mode==='article'?nounArticle(v):mode==='context'?wordTestSession.contextAnswer:recallTarget(v),correct=!skip&&(mode==='full'?fullCorrect(v,a):mode==='article'?norm(a)===norm(target):String(a).normalize('NFC').trim().toLocaleLowerCase('de-DE')===String(target).normalize('NFC').trim().toLocaleLowerCase('de-DE'));wordTestSession.answered=true;wordTestSession.attempts++;if(correct)wordTestSession.score++;else wordTestSession.missed.push(v.id);recordWord(v,mode,correct);contribution('Word Test');const fb=$('#wordTestFeedback');fb.className=`feedback ${correct?'good':'bad'}`;fb.innerHTML=correct?`<div class="answer-study-card"><b>Correct ✓</b><span>${esc(target)}</span></div>`:`<div class="answer-study-card"><b>${skip?`Study this ${wordTestSession.contentType==='words'?'word':'item'}`:'Not quite ✕'}</b><span>Answer:</span><b>${esc(target)}</b></div>`;const normal=$('#wordTestInput');if(normal)normal.disabled=true;$$('.missing-letter-input').forEach(input=>input.disabled=true);$('#wordTestCheck').disabled=true;$('#wordTestSkip').disabled=true;fb.insertAdjacentHTML('beforeend','<div class="button-row" style="justify-content:center;margin-top:12px"><button class="secondary" id="hearWordAnswer">🔊 Listen</button><button class="primary" id="nextWordNow">Next</button></div>');$('#hearWordAnswer').onclick=()=>speakGerman(mode==='context'?v.term:target||v.term);$('#nextWordNow').onclick=advanceWord;wordAdvanceTimer=setTimeout(advanceWord,skip?6500:correct?1600:4200)}
function advanceWord(){clearTimeout(wordAdvanceTimer);if(!wordTestSession)return;wordTestSession.index++;renderWordQuestion()}
function finishWordTest(manual){if(!wordTestSession)return;clearTimeout(wordAdvanceTimer);const s=wordTestSession;state.wordTests.push({date:new Date().toISOString(),mode:s.requested,source:s.source,content:s.contentType,chapter:s.chapterId,score:s.score,attempts:s.attempts,missed:[...new Set(s.missed)]});state.wordTests=state.wordTests.slice(-30);save();$('#wordTestQuestion').classList.add('hidden');$('#wordTestResult').classList.remove('hidden');$('#wordTestProgress').textContent=manual?'Ended':'Completed';$('#wordTestResult').innerHTML=`<div class="test-result"><strong>${s.score} / ${s.attempts}</strong><p>${s.attempts&&s.score/s.attempts>=.8?'Strong session.':'Missed items remain available for review.'}</p><p class="muted">Content: ${s.contentType==='words'?'Words':'Phrases & sentences'} · Full recall is the learning confirmation mode.</p><div class="button-row" style="justify-content:center"><button class="secondary" id="changeTestMode">Change setup</button><button class="primary" id="testAgain">Repeat setup</button></div></div>`;$('#changeTestMode').onclick=()=>renderWordTest();$('#testAgain').onclick=()=>{const cfg={requested:s.requested,source:s.source,contentType:s.contentType,chapterId:s.chapterId};renderWordTest();$('#wordTestMode').value=cfg.requested;$('#wordTestSource').value=cfg.source;$('#wordTestContent').value=cfg.contentType;$('#wordTestChapter').value=cfg.chapterId;$('#wordTestMode').dispatchEvent(new Event('change'));startWordTest()};wordTestSession=null}
