let germanKeyboardTarget=null;
function isGermanTypingField(el){return !!el&&((el.tagName==='TEXTAREA')||(el.tagName==='INPUT'&&!['button','submit','reset','checkbox','radio','file','range','number','date','color'].includes((el.type||'text').toLowerCase())))&&!el.disabled&&!el.readOnly}
function ensureGermanKeyboardUI(){if(!$('#germanKeyboardStyles')){const style=document.createElement('style');style.id='germanKeyboardStyles';style.textContent=`.german-keyboard-toggle{position:fixed;right:18px;bottom:18px;z-index:1200;border-radius:999px;padding:11px 15px;box-shadow:0 8px 28px rgba(0,0,0,.22);background:var(--primary);color:#fff;border:0;font-weight:850;cursor:pointer}.german-keyboard-panel{position:fixed;right:18px;bottom:70px;z-index:1199;width:min(410px,calc(100vw - 36px));padding:12px;border:1px solid var(--border);border-radius:15px;background:var(--panel);box-shadow:0 12px 38px rgba(0,0,0,.25)}.german-keyboard-panel[hidden]{display:none!important}.german-keyboard-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.german-keyboard-head small{color:var(--muted)}.german-key-row{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.german-key{border:1px solid var(--border);background:var(--panel2);color:var(--text);border-radius:11px;padding:12px 10px;font-size:20px;font-weight:850;cursor:pointer}.german-key:hover,.german-key:focus-visible{background:var(--soft);color:var(--primary2);outline:2px solid var(--primary);outline-offset:1px}.german-keyboard-status{margin:9px 0 0;color:var(--muted);font-size:11px;min-height:14px}@media(max-width:560px){.german-keyboard-toggle{right:12px;bottom:12px;width:52px;height:52px;padding:0;border-radius:50%;font-size:0}.german-keyboard-toggle[aria-expanded="false"]:after{content:"Ä";font-size:20px}.german-keyboard-toggle[aria-expanded="true"]:after{content:"×";font-size:24px}.german-keyboard-panel{right:12px;bottom:72px;width:calc(100vw - 24px)}.content{padding-bottom:86px}}`;document.head.appendChild(style)}if($('#germanKeyboardToggle')&&$('#germanKeyboardPanel'))return;const toggle=document.createElement('button');toggle.id='germanKeyboardToggle';toggle.className='german-keyboard-toggle';toggle.type='button';toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-controls','germanKeyboardPanel');toggle.textContent='Show German letters';const panel=document.createElement('div');panel.id='germanKeyboardPanel';panel.className='german-keyboard-panel';panel.hidden=true;panel.innerHTML=`<div class="german-keyboard-head"><div><b>German letters</b><br><small>Inserted at the cursor in the last text field you selected.</small></div><button id="germanKeyboardClose" class="ghost" type="button" aria-label="Hide German letters">✕</button></div><div class="german-key-row"><button class="german-key" type="button" data-char="ä">ä</button><button class="german-key" type="button" data-char="ö">ö</button><button class="german-key" type="button" data-char="ü">ü</button><button class="german-key" type="button" data-char="ß">ß</button></div><p id="germanKeyboardStatus" class="german-keyboard-status">Select a text box, then press a letter.</p>`;document.body.append(toggle,panel)}
function setGermanKeyboardOpen(open){const panel=$('#germanKeyboardPanel'),toggle=$('#germanKeyboardToggle');if(!panel||!toggle)return;panel.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Hide German letters':'Show German letters';try{localStorage.setItem(GERMAN_KEYBOARD_KEY,open?'1':'0')}catch(error){}}
function insertGermanCharacter(char){const target=isGermanTypingField(germanKeyboardTarget)?germanKeyboardTarget:(isGermanTypingField(document.activeElement)?document.activeElement:null),status=$('#germanKeyboardStatus');if(!target){if(status)status.textContent='Select a text box first.';return}target.focus();const start=Number.isInteger(target.selectionStart)?target.selectionStart:target.value.length,end=Number.isInteger(target.selectionEnd)?target.selectionEnd:start;if(typeof target.setRangeText==='function')target.setRangeText(char,start,end,'end');else target.value=target.value.slice(0,start)+char+target.value.slice(end);target.dispatchEvent(new Event('input',{bubbles:true}));target.dispatchEvent(new Event('change',{bubbles:true}));if(status)status.textContent=`Inserted ${char}`}
function initGermanKeyboard(){ensureGermanKeyboardUI();const toggle=$('#germanKeyboardToggle'),close=$('#germanKeyboardClose');if(!toggle)return;document.addEventListener('focusin',event=>{if(isGermanTypingField(event.target)){germanKeyboardTarget=event.target;const status=$('#germanKeyboardStatus');if(status)status.textContent=`Ready for ${event.target.getAttribute('placeholder')||event.target.id||'selected field'}.`}});toggle.addEventListener('click',()=>setGermanKeyboardOpen($('#germanKeyboardPanel').hidden));close?.addEventListener('click',()=>setGermanKeyboardOpen(false));$$('.german-key').forEach(button=>button.addEventListener('mousedown',event=>event.preventDefault()));$$('.german-key').forEach(button=>button.addEventListener('click',()=>insertGermanCharacter(button.dataset.char||button.textContent)));let open=window.innerWidth>900;try{const stored=localStorage.getItem(GERMAN_KEYBOARD_KEY);if(stored!==null)open=stored==='1'}catch(error){}setGermanKeyboardOpen(open)}
function applyLevelBranding(){const mark=$('.brand-mark');if(mark){mark.textContent='B2';mark.setAttribute('aria-label','B2 level');mark.title='Aspekte B2'}}
function heatmap365(){const cells=[],end=new Date();end.setHours(12,0,0,0);const start=new Date(end);start.setDate(end.getDate()-363);let active=0,total=0;for(let i=0;i<364;i++){const d=new Date(start);d.setDate(start.getDate()+i);const k=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,sections=Object.keys(state.contributions[k]||{}),l=sections.length;if(l){active++;total+=l}cells.push(`<span class="heat-cell l${l}${k===today()?' today':''}" title="${k}: ${l}/8${l?' · '+sections.join(', '):''}"></span>`)}const t=Object.keys(state.contributions[today()]||{}),avg=active?(total/active).toFixed(1):'0';return `<div class="contribution-summary">${active} contribution day${active===1?'':'s'} · average ${avg}/8 · today ${t.length}/8</div><div class="heat-wrap"><div class="heatmap">${cells.join('')}</div></div><div class="contribution-sections">${CONTRIB.map(x=>`<span class="${t.includes(x)?'active':''}">${t.includes(x)?'✓ ':''}${esc(x)}</span>`).join('')}</div>`}
function dailyPlanB2(){const out=[];const nextCh=(D.chapters||[]).find(c=>chapterProgress(c).pct<100)||D.chapters?.[0];if(nextCh){const act=chapterExercises(nextCh.id).find(a=>!state.completed[a.id])||chapterExercises(nextCh.id)[0];if(act)out.push({kind:'Course',title:`Kapitel ${nextCh.id} · ${act.label}`,detail:act.title,action:`exercise:${act.id}`})}const due=dueWords();if(due.length)out.push({kind:'Vocabulary',title:`Review ${Math.min(12,due.length)} due words`,detail:`${due.length} currently due`,action:'vocabulary'});else out.push({kind:'Vocabulary',title:'Build vocabulary evidence',detail:`${seenCount()} seen · ${learnedCount()} learned`,action:'vocabulary'});out.push({kind:'Word Test',title:'Active recall session',detail:'Full recall / spelling / articles',action:'wordtest'});const nextAudio=(S.chapterAudio?.[String(nextCh?.id||1)]||[])[0];if(nextAudio)out.push({kind:'Listening',title:`CD ${nextAudio.part} · Track ${String(nextAudio.track).padStart(2,'0')}`,detail:`Kapitel ${nextCh?.id||1}`,action:'audio'});return out.slice(0,4)}
function examUnlock(){const p=overallProgress(),learned=learnedCount(),ready=p.pct>=70&&learned>=20;return {unlocked:true,ready,progress:p.pct,learned,needPages:Math.max(0,70-p.pct),needWords:Math.max(0,20-learned)}}
