function buildExamQuestions(){const grammar=EXAM_GRAMMAR.map(x=>{const correct=x.o[x.a],opts=shuffle(x.o);return {...x,type:'Grammar',o:opts,a:opts.indexOf(correct)}}),vocab=[];for(let ch=1;ch<=10;ch++){const words=V.filter(v=>v.chapter===ch&&!v.core).slice(0,2);words.forEach(v=>{const distract=V.filter(x=>x.chapter===ch&&x.id!==v.id&&x.en!==v.en).slice(0,8).map(x=>x.en);const opts=shuffle([v.en,...distract.slice(0,3)]);vocab.push({ch,type:'Vocabulary',q:`What is the best meaning of “${v.term}”?`,o:opts,a:opts.indexOf(v.en)})})}return [...grammar,...vocab]}
let examSession=null;
function renderFinalExam(){setTitle('Final Exam','B2 course checkpoint');const u=examUnlock(),last=state.exam.history?.at(-1);$('#pageHost').innerHTML=`<section class="panel exam-hero" style="margin-top:0"><div class="panel-head"><div><span class="badge">FINAL COURSE EXAM</span><h2>Aspekte B2 Final Exam</h2><p class="muted">This checkpoint is available whenever you want to test yourself. Readiness is guidance only; it is not a lock.</p></div><span class="exam-lock open">${u.ready?'Ready ✓':'Available'}</span></div><div class="exam-requirements"><div><b>${u.progress}%</b><small>Course exercise progress</small></div><div><b>${u.learned}</b><small>Learned words</small></div><div><b>${buildExamQuestions().length}</b><small>Objective questions</small></div><div><b>${last?Math.round(last.score/last.total*100)+'%':'—'}</b><small>Last attempt</small></div></div>${!u.ready?`<div class="notice"><b>Readiness recommendation:</b> for a more representative final result, aim for 70% course progress and 20 learned words. You can still start now.</div>`:''}<div class="button-row"><button class="primary" id="startFinalExam">Start final exam</button></div></section><section class="panel"><div class="panel-head"><div><h2>Official Prüfungsvorbereitung source</h2><p class="muted">The supplied Lehrbuch contains a Prüfungsvorbereitung page that you can use beside the app checkpoint.</p></div><button class="secondary" id="openOfficialPrep">Open page 195</button></div></section><section class="panel"><h2>What is tested</h2><div class="exam-section-grid"><div><b>Grammar</b><span>20 questions across all 10 chapters</span></div><div><b>Vocabulary</b><span>20 curated course-word meaning questions</span></div><div><b>Writing</b><span>Open self-assessed task saved with the attempt</span></div><div><b>Speaking</b><span>Open preparation notes saved with the attempt</span></div></div></section><div id="examSessionHost"></div>`;$('#openOfficialPrep').onclick=()=>showViewer(198);$('#startFinalExam').onclick=startFinalExam}
function startFinalExam(){const questions=buildExamQuestions();examSession={questions,index:0,answers:Array(questions.length).fill(null),startedAt:new Date().toISOString()};state.exam.startedAt=examSession.startedAt;save();renderExamQuestion()}
function renderExamQuestion(){const host=$('#examSessionHost');if(!examSession||!host)return;const i=examSession.index,q=examSession.questions[i];host.innerHTML=`<section class="panel exam-session"><div class="panel-head"><div><span class="badge">${esc(q.type)} · Kapitel ${q.ch}</span><h2>Question ${i+1} of ${examSession.questions.length}</h2></div><button class="danger-soft" id="endFinalExam">End exam</button></div><div class="progress-bar"><span style="width:${Math.round(i/examSession.questions.length*100)}%"></span></div><div class="exam-question"><h3>${esc(q.q)}</h3><div class="exam-options">${q.o.map((o,n)=>`<label class="exam-option ${examSession.answers[i]===n?'selected':''}"><input type="radio" name="examQ" value="${n}" ${examSession.answers[i]===n?'checked':''}> <span>${esc(o)}</span></label>`).join('')}</div></div><div class="button-row exam-nav"><button class="ghost" id="examBack" ${i===0?'disabled':''}>← Previous</button><button class="primary" id="examNext">${i===examSession.questions.length-1?'Open writing & speaking':'Next →'}</button></div></section>`;$$('input[name="examQ"]').forEach(r=>r.onchange=()=>{examSession.answers[i]=+r.value;renderExamQuestion()});$('#examBack').onclick=()=>{if(i>0){examSession.index--;renderExamQuestion()}};$('#examNext').onclick=()=>{if(examSession.answers[i]===null){alert('Choose an answer or go back later.');return}if(i<examSession.questions.length-1){examSession.index++;renderExamQuestion()}else renderExamOpenTasks()};$('#endFinalExam').onclick=()=>{if(confirm('End this exam attempt?'))finishFinalExam(true)}}
function renderExamOpenTasks(){const host=$('#examSessionHost'),saved=state.exam.open||{};host.innerHTML=`<section class="panel exam-session"><span class="badge">Open production tasks</span><h2>Writing & Speaking</h2><p class="muted">These tasks are saved for self-assessment and are not falsely auto-graded.</p><label class="field-label">Writing · 180–220 words</label><p>Write a structured opinion text about one change you expect in work or society in the next ten years. Give reasons, an example and a conclusion.</p><textarea class="answer-input exam-open" id="examWriting" rows="9" placeholder="Write your B2 text here…">${esc(saved.writing||'')}</textarea>${germanKeyboard('examWriting')}<label class="field-label">Speaking preparation</label><p>Prepare a 3–4 minute contribution: describe a social or technological development, explain advantages and disadvantages, and state your position.</p><textarea class="answer-input exam-open" id="examSpeaking" rows="7" placeholder="Speaking notes…">${esc(saved.speaking||'')}</textarea>${germanKeyboard('examSpeaking')}<div class="button-row"><button class="secondary" id="saveExamOpen">Save for later</button><button class="primary" id="submitFinalExam">Finish & score objective sections</button></div></section>`;wireGermanKeyboard();$('#saveExamOpen').onclick=()=>{state.exam.open={writing:$('#examWriting').value,speaking:$('#examSpeaking').value,savedAt:new Date().toISOString()};contribution('Writing');contribution('Speaking');save();$('#saveExamOpen').textContent='Saved ✓'};$('#submitFinalExam').onclick=()=>{state.exam.open={writing:$('#examWriting').value,speaking:$('#examSpeaking').value,savedAt:new Date().toISOString()};contribution('Writing');contribution('Speaking');finishFinalExam(false)}}
function finishFinalExam(manual){if(!examSession){renderFinalExam();return}let score=0;examSession.questions.forEach((q,i)=>{if(examSession.answers[i]===q.a)score++});const total=examSession.questions.length,p=Math.round(score/total*100),rec={date:new Date().toISOString(),score,total,pct:p,manual,answers:examSession.answers};state.exam.history=state.exam.history||[];state.exam.history.push(rec);state.exam.history=state.exam.history.slice(-10);contribution('Practice');contribution('Grammar');contribution('Vocabulary');save();const host=$('#examSessionHost');host.innerHTML=`<section class="panel test-result"><strong>${score} / ${total}</strong><h2>${p}%</h2><p>${p>=60?'Passed the objective checkpoint ✓':'Below the 60% checkpoint. Review weak chapters and retake.'}</p><div class="button-row" style="justify-content:center"><button class="secondary" id="reviewExam">Review answers</button><button class="primary" id="retakeExam">Retake</button></div><div id="examReview"></div></section>`;$('#reviewExam').onclick=()=>{$('#examReview').innerHTML=`<div class="exam-review-list">${examSession.questions.map((q,i)=>`<div class="exam-review ${examSession.answers[i]===q.a?'ok':'bad'}"><b>${i+1}. ${esc(q.q)}</b><small>Your answer: ${examSession.answers[i]===null?'—':esc(q.o[examSession.answers[i]])} · Correct: ${esc(q.o[q.a])}</small></div>`).join('')}</div>`};$('#retakeExam').onclick=startFinalExam;examSession=null}

function wireCommon(){$$('[data-chapter]').forEach(x=>x.onclick=()=>openChapter(+x.dataset.chapter,'exercises'));$('[data-go-chapters]')?.addEventListener('click',()=>navigate('chapters'));$('[data-open-last]')?.addEventListener('click',()=>openChapter(state.last.chapter||1,state.last.tab||'exercises'))}
$$('.nav-item').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
$('#searchQuick').onclick=()=>navigate('search');
$('#themeBtn').onclick=()=>setTheme(settings.theme==='dark'?'light':'dark');
$('#menuBtn').onclick=()=>{if(matchMedia('(max-width:820px)').matches){document.body.classList.toggle('nav-open');$('#sidebar')?.classList.toggle('open');$('#backdrop')?.classList.toggle('active')}else{settings.sidebarCollapsed=!settings.sidebarCollapsed;localStorage.setItem(SETTINGS,JSON.stringify(settings));applySidebar()}};
$('#backdrop').onclick=()=>{document.body.classList.remove('nav-open');$('#sidebar')?.classList.remove('open');$('#backdrop')?.classList.remove('active')};
$('#viewerClose').onclick=()=>$('#viewer').classList.remove('open');
$('#viewer').onclick=e=>{if(e.target.id==='viewer')$('#viewer').classList.remove('open')};
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#viewer').classList.remove('open')});
applyLevelBranding();applySidebar();initGermanKeyboard();refreshStreak();navigate(state.last.page||'home');window.addEventListener('resize',applySidebar);if(cloudReady())setTimeout(()=>cloudSyncNow(null,true),800);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js?v=0.6.0').catch(()=>{}));
